args.sql:
SELECT COUNT(*) FROM riskanalysis ra
JOIN transactions t ON ra.txref = t.txregistry
WHERE (ra.txchainlen * 10) + (ra.linkedtxcount * 5) + (ra.fraudprob * 100) - (ra.profilecomplete * 0.5) - (ra.idverifyscore * 0.5) > 150;

SELECT txchainlen, linkedtxcount, fraudprob, profilecomplete, idverifyscore, 
    (txchainlen * 10) + (linkedtxcount * 5) + (fraudprob * 100) - (profilecomplete * 0.5) - (idverifyscore * 0.5) AS tcr
FROM riskanalysis LIMIT 5;

SELECT COUNT(*) FROM riskanalysis 
WHERE (txchainlen * 10) + (linkedtxcount * 5) + (fraudprob * 100) - (profilecomplete * 0.5) - (idverifyscore * 0.5) > 150
AND wallage < 30 AND wallturnrt > 5 AND linkedtxcount >= 3;

